p=argparse.ArgumentParser();p.add_argument('root',type=Path);root=p.parse_args().root;summary=json.loads((root/'summary.json').read_text());audit=json.loads((root/'independent-validation.json').read_text());cost=json.loads((root/'cost.json').read_text());details=json.loads((root/'joint-analysis.json').read_text())
